    correctKey: 'B',
    explanation: '均等積立方式は、長期修繕計画の対象期間を通じて、毎月の修繕積立金の額を一定に保つ方式であり、当初から必要な水準の積立金を徴収するため、将来の資金不足リスクが相対的に低いとされる。これに対し段階増額積立方式は、当初の負担（引越し当初の一時金や当初の積立額）を抑える目的で、将来的に段階的に積立額を増額していく方式であるが、将来の増額決議が総会で否決される等して計画どおりに増額されない場合、修繕積立金が計画に対して不足するリスクがある。国土交通省のガイドライン等では、こうしたリスクを踏まえ、均等積立方式がより望ましいとの考え方が示されている。',
